import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%A1%E3%83%A2%E3%82%92%E3%82%A2%E3%83%97%E3%83%AA%E3%82%B1%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%81%AB%E4%BE%9D%E5%AD%98%E3%81%95%E3%81%9B%E3%81%9F%E3%81%8F%E3%81%AA%E3%81%84.html","title":"メモをアプリケーションに依存させたくない","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.86,"words":258},"filePathRelative":"メモをアプリケーションに依存させたくない.md"}`),a={name:`メモをアプリケーションに依存させたくない.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="メモをアプリケーションに依存させたくない" tabindex="-1"><a class="header-anchor" href="#メモをアプリケーションに依存させたくない"><span>メモをアプリケーションに依存させたくない</span></a></h1><p><a href="./ノート.html">ノート</a>より</p><p><a href="./Wikiとhowmとメモツール.html">Wikiとhowmとメモツール</a>的な事をまた考えていた。WIkiNameを作るのはやっぱりかったるい。 特に今日は、どこに作るのかを考えるのがかったるい、という問題を考えていた。 WikiNameのファイル名のmdはこれで良いと思っているとする。</p><p>で、単にWikiNameのmdファイルを作って置くだけにしてたどる方を後からどうにかする方向でなんとかならんかなぁ、と考えて、 ハッシュタグとかバックリンクがあればいいかな、という気はしていた。</p><p>でも<a href="./SAF.html">SAF</a>は結構遅いので、この<a href="./RandomThoughts.html">RandomThoughts</a>を表示する都度毎回全部検索させるのもちょっと躊躇する（どのくらい掛かるかは試してないが）。 Github Pagesに公開する時にバックリンクを生成するスクリプトは、まぁやれば出来そうだが、webでしか使えない機能にはあんまり依存したくないよなぁ。</p><p>とそこまで考えて思った事として、メモをアプリケーションの機能にあまり依存させたくは無いよなぁ、と思った。 Unix的ファイルのファイル名やディレクトリのルールに依存するのはいい。 けれどアプリの方でいろいろやる結果実現される機能を、メモの前提にはしたくない。 <a href="./SAF.html">SAF</a>で使いたい、となった時にすぐに使えないのは困る。Github Pagesで公開したい、 と思った時にすぐに公開出来ないのは嫌だ。</p><p>やはりメモをアプリの機能を前提としたものにはしたくないな、と思う。 そのアプリより長生きする事はもうこれまでの経験から確信を持てるので、メモはアプリの機能には依存せず、メモの構造にアプリの方を依存させたい。</p><p>メモに必要な機能を、なるべくファイル名とディレクトリ構造とテキストファイルのルールで実現したい。 バックリンクは少しむずかしい。と思ったがRandomThoughtsを今ls wcしたら500ファイルくらいだ。このくらいならさすがにイケるか？ でもRecents作るのも結構遅いくらいだからなぁ、SAF。</p><p>バッチ処理でバックリンクを作るのはどうだろう？全ファイルからリンクとそのファイル名のペアを列挙してsortすれば作る事自体はO(n)だろうから、 PCなら一瞬、SAFでも数秒って所だろう。 WikiNameと同じ名前のファイル名でバックリンクのファイル名が一行1レコードで入っていれば、そのファイルのバックリンクを調べるのはファイル開くだけなのでSAFでも問題は無さそうだし、このファイルはSyncthingで共有すれば他の環境でも動きそうだ。 ただどこに置くかはちょっと悩ましいな。.backlinkというディレクトリの中か？ なんかあんまりこういうファイルは置きたくない気持ちもある。</p><p>まぁ数秒くらいなら、バックリンクを表示したい、と思った時に生成するくらいは許されるかもしれない。単にページ表示する都度毎回やるには重いが。 この辺はやってみないと分からないなぁ。</p><p>ということを考えていてシェルスクリプトで試してみる事にした＞<a href="./Wikiのリンクを扱うシェルスクリプト.html">Wikiのリンクを扱うシェルスクリプト</a>へ。</p><p>試した結果、2ホップリンクなどはメモの構造の方をそれ前提にしないとあまり有効に機能しないという結論になる。 この機能はちょっとアプリケーション寄り過ぎて、メモの構造をそれにあわせるのはちょっと気が乗らない。</p><p>やはり最悪エディタとちょっとしたワンライナーとlessとかでいいや、と思える形にしたいよなぁ。 <a href="./Wikiのリンクを扱うシェルスクリプト.html">Wikiのリンクを扱うシェルスクリプト</a>くらいはまぁいつでも作れると言えば作れるが。</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};